H.background();
const vt = P.vt, m = P.m;
const g = 9.8;
const W = m * g;
const b = vt > 0.5 ? W / (vt * vt) : W / 0.25;
H.text("Terminal velocity: drag grows until F_drag = mg", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Object falls; quadratic drag b*v^2 rises until it cancels weight, then v is constant", 24, 52, { color: H.colors.sub, size: 13 });
const tau = vt / g;
const cyc = (t % 8);
const v = vt * (1 - Math.exp(-cyc / Math.max(tau, 0.05)));
const Fd = b * v * v;
const Fnet = W - Fd;
const px = 250;
const groundY = H.H - 60;
const topY = 110;
const drop = (cyc / 8);
const ballY = topY + drop * (groundY - topY - 40);
H.line(120, groundY, H.W - 60, groundY, { color: H.colors.grid, width: 2 });
H.circle(px, ballY, 18, { fill: H.colors.accent2, stroke: H.colors.ink, width: 2 });
const wScale = 1.4;
H.arrow(px, ballY + 18, px, ballY + 18 + W * wScale, { color: H.colors.warn, width: 4 });
H.text("mg = " + W.toFixed(1) + " N", px + 12, ballY + 18 + W * wScale, { color: H.colors.warn, size: 12 });
H.arrow(px, ballY - 18, px, ballY - 18 - Fd * wScale, { color: H.colors.good, width: 4 });
H.text("F_drag = " + Fd.toFixed(1) + " N", px + 12, ballY - 18 - Fd * wScale * 0.5, { color: H.colors.good, size: 12 });
const view = H.plot2d({ xMin: 0, xMax: 8, yMin: 0, yMax: vt * 1.25 + 1 });
view.grid(); view.axes();
view.fn(x => vt * (1 - Math.exp(-x / Math.max(tau, 0.05))), { color: H.colors.accent, width: 3 });
view.line(0, vt, 8, vt, { color: H.colors.violet, width: 2, dash: [6, 4] });
view.text("v_t = " + vt.toFixed(1) + " m/s", 0.3, vt, { color: H.colors.violet, size: 12 });
view.dot(cyc, v, { r: 6, fill: H.colors.accent2 });
H.text("v = " + v.toFixed(2) + " m/s   F_net = " + Fnet.toFixed(1) + " N", 24, 78, { color: H.colors.sub, size: 13 });
H.legend([{ label: "weight mg (down)", color: H.colors.warn }, { label: "drag b v^2 (up)", color: H.colors.good }], 24, 96);
